cols = ["area","stage","title","evidence","url","severity","heuristic","impact","effort","fix","service","confidence","source"]
L={4:"Critical",3:"Major",2:"Minor",1:"Cosmetic"}
rows=[]
for i,f in enumerate(F):
    r={"id":"F%02d"%(i+1)}; r.update(dict(zip(cols,f))); r["severity_label"]=L[r["severity"]]; rows.append(r)
json.dump(rows, open(OUT,"w"), ensure_ascii=False, indent=1)
from collections import Counter
print(len(rows), Counter(r["severity"] for r in rows))
for r in rows: print(r["id"], r["severity"], r["title"][:60])
